namespace Challenge;public enum PaymentStatus{Success,Transient,Permanent,CircuitOpen}public interface IPaymentProvider{Task<PaymentStatus> SendAsync(string key,CancellationToken ct);}public sealed class PaymentClient(IPaymentProvider provider){int exhausted;public async Task<PaymentStatus> PayAsync(string key,CancellationToken ct=default){ct.ThrowIfCancellationRequested();if(Volatile.Read(ref exhausted)>=2)return PaymentStatus.CircuitOpen;for(int i=0;i<3;i++){ct.ThrowIfCancellationRequested();var s=await provider.SendAsync(key,ct);if(s==PaymentStatus.Success){Interlocked.Exchange(ref exhausted,0);return s;}if(s==PaymentStatus.Permanent)return s;}Interlocked.Increment(ref exhausted);return PaymentStatus.Transient;}}
